// Owner-room numbers are recomputed at most every 5 minutes (P36d reads 9 sheets); events are read on every call.
// Los números de la oficina de la dueña se recalculan máximo cada 5 minutos (P36d lee 9 hojas); los eventos, en cada llamada.
const CACHE_MIN = 5;
const sd = $getWorkflowStaticData('global');
const fresh = sd.kpis && Date.now() - (sd.at || 0) < CACHE_MIN * 60 * 1000;
const tz = 'America/Phoenix';
const today = $now.setZone(tz);
return [{ json: { refresh: !fresh, desde: today.minus({ days: 29 }).toFormat('yyyy-MM-dd'), hasta: today.toFormat('yyyy-MM-dd') } }];

// Keeps only what the office shows (no client data) / Guarda solo lo que muestra la oficina (sin datos de clientas)
const m = $input.first().json;
const P = m.periodo || {};
const sd = $getWorkflowStaticData('global');
sd.kpis = {
  dias: P.dias, leads: P.leads, respuesta_prom_seg: P.respuesta_prom_seg, citas_agendadas: P.citas_agendadas,
  no_shows_evitados: P.no_shows_evitados, clientas_que_vuelven: P.clientas_que_vuelven, citas_recuperadas: (P.citas_de_nurturing || 0) + (P.clientas_que_vuelven || 0),
  resenas_pedidas: P.resenas_pedidas, horas_ahorradas: P.horas_ahorradas, total_usd: P.total_usd, costo_sistema_usd: P.costo_sistema_usd, roi_x: P.roi_x,
  casos_abiertos: m.casos_abiertos
};
sd.at = Date.now();
return [{ json: { cached: true } }];

// Feed for the pixel-art office (live mode): last events + owner-room numbers. Read only, first names only.
// Feed de la oficina pixel art (modo en vivo): últimos eventos + números de la dueña. Solo lectura y solo nombres de pila.
// Query: ?since=<evento_id> → only newer events (the page polls every few seconds).
const MAX = 40;
const q = $('Office Feed').first().json.query || {};
const since = String(q.since || '');
const sd = $getWorkflowStaticData('global');
const rows = (($input.first().json.values) || []).slice(1).filter(r => r[0]);
let ev = rows.map(r => ({ id: r[0], fecha: r[1], tipo: r[2], proyecto: r[3], ref: String(r[5] || '').slice(0, 3), detalle: String(r[6] || '') }));
if (since) { const i = ev.findIndex(e => e.id === since); ev = i >= 0 ? ev.slice(i + 1) : ev; }
ev = ev.slice(-MAX).map(e => ({ ...e, detalle: e.tipo === 'error' ? 'Falla en ' + e.proyecto + ' · el monitor ya avisó' : e.detalle }));   // no technical details on screen
return [{ json: { ok: true, modo: 'en_vivo', ahora: $now.setZone('America/Phoenix').toFormat('yyyy-MM-dd HH:mm:ss'),
  kpis: sd.kpis || null, kpis_at: sd.at || null, eventos: ev, ultimo: rows.length ? rows[rows.length - 1][0] : '' } }];
